def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 2 and
                grid[r+1][c] == 2 and grid[r][c-1] == 2 and
                grid[r][c+1] == 2):
                centers.append((r, c))

    # Link consecutive diamond centers along each shared row or column.
    for r in range(h):
        row_centers = sorted(c for rr, c in centers if rr == r)
        for c1, c2 in zip(row_centers, row_centers[1:]):
            for c in range(c1 + 1, c2):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        col_centers = sorted(r for r, cc in centers if cc == c)
        for r1, r2 in zip(col_centers, col_centers[1:]):
            for r in range(r1 + 1, r2):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
